/* Apprentice Pathways Explorer — offline support (generated by tools/build.js) */
const CACHE = 'ape-ee0547d0e0';
const PRECACHE = ["./","index.html","trades.html","careers.html","skills.html","planner.html","opportunities.html","dashboard.html","offline.html","css/style.css","js/data.js","js/render.js","js/scenes.js","js/config.js","js/app.js","manifest.webmanifest","icons/icon.svg","icons/icon-192.png"];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  // Never cache the AI endpoint
  if (url.pathname.startsWith('/api/')) return;
  if (req.mode === 'navigate') {
    // Pages: try the network first so content stays fresh, fall back to the saved copy
    event.respondWith(fetch(req).then((res) => {
      const copy = res.clone();
      caches.open(CACHE).then((c) => c.put(req, copy));
      return res;
    }).catch(() => caches.match(req).then((hit) => hit || caches.match('offline.html'))));
    return;
  }
  // Files and fonts: use the saved copy, refresh it in the background
  event.respondWith(caches.match(req).then((hit) => {
    const net = fetch(req).then((res) => {
      if (res && (res.ok || res.type === 'opaque')) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
      return res;
    }).catch(() => hit);
    return hit || net;
  }));
});
